// mobile-keyboard.js -- touch-first virtual keyboard for the LilyPond editor.
//
// Sits above the phone's software keyboard: large keys for pitches,
// durations, bar checks and structure; long-press for alternates; a
// command picker and template inserter sourced from window.LILYPOND_SYNTAX
// (same data the palette uses, generated by scripts/build-syntax.js).
//
// Inserts use editor.setRangeText so the browser keeps the undo stack,
// then scheduleCompile(true) like palette.js. No new dependencies.

(function () {
  "use strict";

  var editor = document.getElementById("editor");
  var host = document.getElementById("mobileKeyboard");
  var data = window.LILYPOND_SYNTAX;
  if (!editor || !host || !data) return;

  var LAYERS = {
    note: [
      [
        { k: "c", t: "c", long: ["cis", "des"] },
        { k: "d", t: "d", long: ["dis", "es"] },
        { k: "e", t: "e", long: ["eis", "fes"] },
        { k: "f", t: "f", long: ["fis", "ges"] },
        { k: "g", t: "g", long: ["gis", "as"] },
        { k: "a", t: "a", long: ["ais", "bes"] },
        { k: "b", t: "b", long: ["bis", "ces"] },
      ],
      [{ k: "'", t: "'", hint: "↑oct" }, { k: ",", t: ",", hint: "↓oct" }, { k: "1", t: "1", hint: "whole" }, { k: "2", t: "2", hint: "half" }, { k: "4", t: "4", hint: "qrtr", primary: true }, { k: "8", t: "8", hint: "8th" }, { k: ".", t: ".", hint: "dot" }],
      [{ k: "r", t: "r", hint: "rest" }, { k: "R", t: "R", hint: "full-m" }, { k: "s", t: "s", hint: "spacer" }, { k: "~", t: "~", hint: "tie" }, { k: "-", t: "-", hint: "script", long: ["-.", "-^", "-_", "-!", "--", "-+"] }, { k: "^", t: "^", hint: "up" }, { k: "_", t: "_", hint: "down" }],
      [{ k: "{", t: "{", pair: "}" }, { k: "}", t: "}" }, { k: "<", t: "<", pair: ">", hint: "chord" }, { k: ">", t: ">" }, { k: "|", t: "|", primary: true, wide: true, hint: "bar" }, { k: "\\", t: "\\", action: "picker", hint: "cmd" }, { k: " ", t: "␣", wide: true }],
    ],
    chord: [
      [
        { k: "c", t: "c", long: ["cis", "des"] },
        { k: "d", t: "d", long: ["dis", "es"] },
        { k: "e", t: "e", long: ["eis", "fes"] },
        { k: "f", t: "f", long: ["fis", "ges"] },
        { k: "g", t: "g", long: ["gis", "as"] },
        { k: "a", t: "a", long: ["ais", "bes"] },
        { k: "b", t: "b", long: ["bis", "ces"] },
      ],
      [{ k: ":", t: ":", primary: true, hint: "qual" }, { k: "/", t: "/", hint: "inv" }, { k: "m", t: "m", hint: "minor" }, { k: "7", t: "7", hint: "dom7" }, { k: "M", t: "maj7", hint: "maj7" }, { k: "D", t: "dim", hint: "dim" }, { k: "A", t: "aug", hint: "aug" }],
      [{ k: "S", t: "sus4", hint: "sus4" }, { k: "6", t: "6" }, { k: "9", t: "9" }, { k: "1", t: "1" }, { k: "2", t: "2" }, { k: "4", t: "4", primary: true }, { k: ".", t: "." }],
      [{ k: "<", t: "<", pair: ">", hint: "grid" }, { k: ">", t: ">" }, { k: "~", t: "~", hint: "hold" }, { k: "|", t: "|", primary: true, wide: true, hint: "bar" }, { k: "\\", t: "\\", action: "picker" }, { k: " ", t: "␣", wide: true }],
    ],
    lyric: [
      [{ k: " -- ", t: "--", primary: true, hint: "hyphen" }, { k: " __ ", t: "__", primary: true, hint: "extender" }, { k: "_", t: "_", hint: "skip" }, { k: "1", t: "1" }, { k: "2", t: "2" }, { k: "4", t: "4" }, { k: "8", t: "8" }],
      [{ k: '"', t: '"', pair: '"' }, { k: "'", t: "'", pair: "'" }, { k: "-", t: "-" }, { k: "(", t: "(", pair: ")" }, { k: ")", t: ")" }, { k: ",", t: "," }, { k: ".", t: "." }],
      "abcdefghijklmnopqrstuvwxyz".split("").map(function (c) { return { k: c, t: c }; }),
      [{ k: " ", t: "␣", wide: true }, { k: null, t: "⌫", action: "backspace", wide: true }, { k: "\n", t: "⏎" }, { k: "|", t: "|", primary: true, wide: true }],
    ],
    markup: [
      ["\\markup", "\\bold", "\\italic", "\\small", "\\large", "\\column", "\\center-column"].map(function (c) { return { k: c, t: c.replace("\\", "\\"), insert: c + " { }", hint: "markup" }; }),
      ["\\box", "\\circle", "\\pad-around", "\\musicglyph", "\\note", "\\rest", "\\fermata"].map(function (c) {
        var insert = c === "\\musicglyph" ? '\\musicglyph #"scripts.segno"' : c + (c === "\\note" ? ' #"4" #1' : c === "\\rest" ? ' #"4"' : c === "\\fermata" ? "" : " { }");
        return { k: c, t: c, insert: insert, hint: "markup" };
      }),
      [{ k: "\\mark", t: "\\mark", insert: '\\mark \\markup { "A" }', hint: "rehearsal" }, { k: "^", t: "^", hint: "above" }, { k: "_", t: "_", hint: "below" }, { k: "-", t: "-", hint: "auto" }, { k: "{", t: "{", pair: "}" }, { k: "}", t: "}" }],
      [{ k: " ", t: "␣", wide: true }, { k: null, t: "⌫", action: "backspace", wide: true }, { k: "|", t: "|", primary: true, wide: true }, { k: "\\", t: "\\", action: "picker" }],
    ],
    scheme: [
      [{ k: "#", t: "#", primary: true, hint: "scheme" }, { k: "##", t: "##", hint: "bool" }, { k: "(", t: "(", pair: ")" }, { k: ")", t: ")" }, { k: "{", t: "{", pair: "}" }, { k: "}", t: "}" }, { k: "'", t: "'", pair: "'", hint: "quote" }],
      [{ k: null, t: "define-music-fn", insert: "myFn =\n#(define-music-function\n  (note)\n  (ly:music?)\n  #{ $note ^\\markup { \\bold \">\" } #})\n" }, { k: null, t: "define", insert: "#(define (name args) body)" }, { k: null, t: "lambda", insert: "#(lambda (args) body)" }, { k: null, t: "if", insert: "#(if test then else)" }, { k: null, t: "begin", insert: "#(begin expr1 expr2)" }, { k: null, t: "display", insert: '#(begin (display "msg") (newline))' }, { k: null, t: "use-modules", insert: "#(use-modules (ice-9 optargs))" }],
      [{ k: "ly:music?", t: "ly:music?" }, { k: "ly:pitch?", t: "ly:pitch?" }, { k: "ly:duration?", t: "ly:duration?" }, { k: "ly:make-music", t: "make-music" }, { k: "ly:parser-output-name", t: "parser-output" }, { k: "x11-color", t: "x11-color" }, { k: "#t", t: "##t", hint: "true" }],
      [{ k: " ", t: "␣", wide: true }, { k: null, t: "⌫", action: "backspace", wide: true }, { k: "|", t: "|", primary: true, wide: true }, { k: "\\", t: "\\", action: "picker" }],
    ],
  };

  var currentLayer = "note";
  var pickerEl = null, pickerList = null, pickerSearch = null, templatesEl = null;

  function triggerCompile() {
    if (typeof scheduleCompile === "function") scheduleCompile(true);
    else editor.dispatchEvent(new Event("input", { bubbles: true }));
  }

  function insert(text) {
    editor.setRangeText(text, editor.selectionStart, editor.selectionEnd, "end");
    triggerCompile();
    editor.focus();
  }

  function backspace() {
    var s = editor.selectionStart, e = editor.selectionEnd;
    if (s !== e) editor.setRangeText("", s, e, "start");
    else if (s > 0) editor.setRangeText("", s - 1, s, "start");
    triggerCompile();
    editor.focus();
  }

  function autoPair(open, close) {
    var s = editor.selectionStart, e = editor.selectionEnd;
    var after = editor.value.slice(e);
    if (after.charAt(0) === close) {
      editor.selectionStart = editor.selectionEnd = e + 1;
      editor.focus();
      return;
    }
    editor.setRangeText(open + close, s, e, "end");
    editor.selectionStart = editor.selectionEnd = s + 1;
    triggerCompile();
    editor.focus();
  }

  function longPressAlt(k) {
    if (!k.long || !k.long.length) return false;
    var msg = 'Alternates for "' + k.k + '":\n' + k.long.map(function (v, i) { return (i + 1) + ": " + v; }).join("\n") + "\n0: cancel";
    var ans = window.prompt(msg, "1");
    if (ans && ans !== "0" && k.long[+ans - 1]) { insert(k.long[+ans - 1]); return true; }
    return true;
  }

  function renderLayer(name) {
    var layer = LAYERS[name];
    if (!layer) return;
    currentLayer = name;
    host.innerHTML = "";

    layer.forEach(function (row) {
      var rowEl = document.createElement("div");
      rowEl.className = "mk-row";
      row.forEach(function (k) {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "mk-key" + (k.primary ? " mk-primary" : "") + (k.wide ? " mk-wide" : "");
        btn.textContent = k.t;
        if (k.hint) btn.setAttribute("data-hint", k.hint);

        var timer = null;
        btn.addEventListener("touchstart", function () {
          if (k.long && k.long.length) timer = setTimeout(function () { longPressAlt(k); timer = null; }, 350);
        }, { passive: true });
        btn.addEventListener("touchend", function () { if (timer) clearTimeout(timer); });
        btn.addEventListener("touchmove", function () { if (timer) clearTimeout(timer); });

        btn.addEventListener("click", function (ev) {
          ev.preventDefault();
          if (k.action === "backspace") return backspace();
          if (k.action === "picker") return openPicker();
          if (k.insert) return insert(k.insert);
          if (k.pair) return autoPair(k.k, k.pair);
          if (k.k == null) return;
          insert(k.k);
        });
        rowEl.appendChild(btn);
      });
      host.appendChild(rowEl);
    });

    // bottom bar
    var bar = document.createElement("div");
    bar.className = "mk-bottombar";
    [["undo", "↶", function () { try { document.execCommand("undo"); } catch (_) {} }],
     ["redo", "↷", function () { try { document.execCommand("redo"); } catch (_) {} }],
     ["note", "Note", function () { renderLayer("note"); }],
     ["chord", "Chord", function () { renderLayer("chord"); }],
     ["lyric", "Lyric", function () { renderLayer("lyric"); }],
     ["markup", "Markup", function () { renderLayer("markup"); }],
     ["scheme", "Scheme", function () { renderLayer("scheme"); }],
     ["templates", "Templates", function () { openTemplates(); }],
     ["hide", "⌨", function () { toggleHost(); }]
    ].forEach(function (b) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "mk-key mk-bb" + (currentLayer === b[0] ? " mk-primary" : "");
      btn.textContent = b[1];
      btn.addEventListener("click", function (ev) { ev.preventDefault(); b[2](); });
      bar.appendChild(btn);
    });
    host.appendChild(bar);
  }

  // ---- command picker (reads window.LILYPOND_SYNTAX) --------------------
  function buildCommands() {
    var out = [];
    (data.categories || []).forEach(function (cat) {
      (cat.entries || []).forEach(function (e) {
        if (e.insert && e.kind !== "note" && e.kind !== "warning" && e.kind !== "template") {
          out.push({ cat: cat.id, name: e.name, insert: e.insert, scope: e.scope, syntax: e.syntax || "" });
        }
      });
    });
    return out;
  }
  var COMMANDS = buildCommands();

  function openPicker() {
    if (!pickerEl) {
      pickerEl = document.createElement("div");
      pickerEl.className = "mk-picker";
      pickerEl.innerHTML = '<div class="mk-picker-head"><input type="search" class="mk-search" placeholder="Search commands…"><button type="button" class="mk-key">Done</button></div><div class="mk-picker-list"></div>';
      pickerList = pickerEl.querySelector(".mk-picker-list");
      pickerSearch = pickerEl.querySelector(".mk-search");
      pickerEl.querySelector("button").addEventListener("click", closePicker);
      pickerSearch.addEventListener("input", function () { renderPickerList(pickerSearch.value); });
      document.body.appendChild(pickerEl);
    }
    pickerEl.hidden = false;
    pickerSearch.value = "";
    renderPickerList("");
    pickerSearch.focus();
  }
  function closePicker() { if (pickerEl) pickerEl.hidden = true; }

  function renderPickerList(q) {
    q = (q || "").toLowerCase();
    var items = COMMANDS.filter(function (c) {
      return !q || c.name.toLowerCase().indexOf(q) >= 0 || c.cat.indexOf(q) >= 0 || (c.syntax || "").toLowerCase().indexOf(q) >= 0;
    }).slice(0, 60);
    pickerList.innerHTML = "";
    items.forEach(function (c) {
      var div = document.createElement("button");
      div.type = "button";
      div.className = "mk-picker-item";
      div.innerHTML = '<span class="mk-picker-cat">' + c.cat + ' · ' + c.scope + '</span><span class="mk-picker-cmd">' + c.name + '</span>';
      div.addEventListener("click", function () { insert(c.insert); closePicker(); });
      pickerList.appendChild(div);
    });
    if (!items.length) pickerList.innerHTML = '<div class="mk-picker-empty">No matches</div>';
  }

  // ---- templates ---------------------------------------------------------
  function openTemplates() {
    if (!templatesEl) {
      templatesEl = document.createElement("div");
      templatesEl.className = "mk-picker";
      templatesEl.innerHTML = '<div class="mk-picker-head"><strong style="flex:1;padding-top:6px">Insert whole-score template (replaces all)</strong><button type="button" class="mk-key">Cancel</button></div><div class="mk-picker-list mk-templates"></div>';
      templatesEl.querySelector("button").addEventListener("click", function () { templatesEl.hidden = true; });
      document.body.appendChild(templatesEl);
    }
    var list = templatesEl.querySelector(".mk-picker-list");
    list.innerHTML = "";
    (data.categories || []).forEach(function (cat) {
      if (cat.id !== "templates") return;
      (cat.entries || []).forEach(function (e) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "mk-picker-item";
        b.innerHTML = '<span class="mk-picker-cmd">' + e.name + '</span>';
        b.addEventListener("click", function () {
          if (window.confirm('Replace editor with "' + e.name + '"?')) {
            editor.value = e.insert;
            templatesEl.hidden = true;
            triggerCompile();
          }
        });
        list.appendChild(b);
      });
    });
    templatesEl.hidden = false;
  }

  // show/hide toggle button next to the editor
  var toggle = document.createElement("button");
  toggle.type = "button";
  toggle.id = "mkToggle";
  toggle.textContent = "⌨ Keys";
  toggle.setAttribute("aria-label", "Toggle virtual keyboard");
  function overlayMode() {
    // Reserve space so the fixed keyboard never covers the editor/preview.
    document.body.style.paddingBottom = host.hidden ? "" : host.offsetHeight + "px";
  }

  function toggleHost() {
    host.hidden = !host.hidden;
    toggle.textContent = host.hidden ? "⌨ Keys" : "⌨ Hide";
    overlayMode();
  }

  toggle.addEventListener("click", toggleHost);
  var actions = document.querySelector(".header-actions") || document.body;
  actions.appendChild(toggle);

  window.addEventListener("resize", overlayMode);

  renderLayer("note");
  // Auto-open on small touch screens only.
  host.hidden = !(window.matchMedia && window.matchMedia("(max-width: 900px) and (pointer: coarse)").matches);
  toggle.textContent = host.hidden ? "⌨ Keys" : "⌨ Hide";
  overlayMode();
})();
